import type { LlmMessage } from "../api/client.js";
import { DEFAULT_PROFILE_ID } from "./profiles.js";

/** localStorage keys for the persisted conversations and the active one. */
const STORAGE_CONVS = "vise:llm:conversations";
const STORAGE_ACTIVE = "vise:llm:active";
/** Legacy single-conversation keys, read once for migration then ignored. */
const LEGACY_HISTORY = "vise:llm:history";
const LEGACY_MODEL = "vise:llm:model";

/**
 * `endHook` marks a synthetic `user` message generated by the end-of-turn
 * hook when it blocks a turn (stderr present): it carries the hook's
 * truncated stdout/stderr back to the model as the next turn's prompt, and is
 * rendered as a distinct "end-of-turn check" block rather than a plain user
 * bubble (see messageView.ts's expandMessage).
 *
 * The `compaction` flag marks a model-generated summary that stands in for
 * all turns before it: when present, only that summary and the turns after
 * it are sent to the model. The message array is append-only — nothing
 * before a summary is ever removed from it, only bypassed in the outgoing
 * prompt.
 *
 * `reasoning` carries the model's chain-of-thought for an assistant reply
 * (the proxy streams it separately from `content`). It is display-only: it is
 * never sent back to the model, so it does not affect the outgoing prompt.
 */
export type ChatMessage = Omit<LlmMessage, "content"> & {
  /** Stored messages are always text; images ride in `images` instead. */
  content: string | null;
  /**
   * On a `tool` message, the images (data URLs) the tool returned. The wire
   * form is built from it (see llm.ts's buildMessages: a follow-up user
   * message, latest only) and it is never persisted (too big for
   * localStorage), so a reloaded conversation keeps only the tool's text.
   */
  images?: string[];
  compaction?: true;
  endHook?: true;
  reasoning?: string;
};

/**
 * A conversation is a self-contained chat: its message history, model
 * choice, and the profile it runs under. Conversations are independent of
 * one another and are listed in the panel so the user can start new ones and
 * reopen old ones.
 */
export interface Conversation {
  id: string;
  title: string;
  model: string;
  messages: ChatMessage[];
  /**
   * The id of the Profile (see profiles.ts) this conversation runs under. The
   * profile is the sole source of truth for the conversation's system
   * prompt, allowed tools, and hook commands — a conversation carries no
   * tool/hook settings of its own. Defaults to the always-present default
   * profile.
   */
  profileId: string;
  /**
   * The active profile's startup-hook output, captured the first time it
   * runs for this conversation. Undefined means it hasn't run yet (or the
   * profile has no startup hook); once set, it is reused for every later
   * turn's system prompt instead of re-running the command. This is cached
   * per-conversation (not on the profile) because a startup hook typically
   * captures context-specific state (e.g. `git status`) that two
   * conversations sharing a profile at different times shouldn't share.
   */
  hookOutput?: string;
  /**
   * The workspace root's AGENTS.md text, loaded once per conversation and
   * cached here so later turns (and any subagents delegated from this
   * conversation) reuse it instead of re-fetching the file every turn.
   * `undefined` until the first successful load (which also covers
   * conversations created before this field existed, and a failed fetch —
   * e.g. the file is missing — which a later turn retries); once loaded it
   * holds the trimmed text, or `""` when the file is present but empty.
   * Either falsy value contributes nothing to the prompt.
   */
  agentsMd?: string;
}

/** True when `value` is a structurally valid persisted message. */
function isValidMessage(value: unknown): value is ChatMessage {
  return (
    typeof value === "object" &&
    value !== null &&
    (value as LlmMessage).role in { user: true, assistant: true, tool: true } &&
    (typeof (value as LlmMessage).content === "string" ||
      (value as LlmMessage).content === null) &&
    ((value as ChatMessage).reasoning === undefined ||
      typeof (value as ChatMessage).reasoning === "string")
  );
}

/** True when `value` is a structurally valid persisted conversation. */
function isValidConversation(value: unknown): value is Conversation {
  if (typeof value !== "object" || value === null) return false;
  const c = value as Record<string, unknown>;
  return (
    typeof c.id === "string" &&
    typeof c.title === "string" &&
    typeof c.model === "string" &&
    Array.isArray(c.messages) &&
    (c.messages as unknown[]).every(isValidMessage) &&
    (c.profileId === undefined || typeof c.profileId === "string") &&
    (c.hookOutput === undefined || typeof c.hookOutput === "string") &&
    (c.agentsMd === undefined || typeof c.agentsMd === "string")
  );
}

/** Generate a unique id for a new conversation. */
function newId(): string {
  try {
    if (
      typeof crypto !== "undefined" &&
      typeof crypto.randomUUID === "function"
    ) {
      return crypto.randomUUID();
    }
  } catch {
    // Fall through to the timestamp id.
  }
  return `c${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
}

/**
 * Derive a short display title from a conversation: the first user message,
 * trimmed and truncated. For an empty conversation, falls back to a generic
 * label; when `idSuffix` is given (a fragment of the conversation's id) it is
 * appended so several empty conversations stay distinguishable in the list.
 */
export function deriveTitle(
  messages: ChatMessage[],
  idSuffix?: string
): string {
  for (const m of messages) {
    if (
      m.role === "user" &&
      typeof m.content === "string" &&
      m.content.trim()
    ) {
      const t = m.content.trim().replace(/\s+/g, " ");
      return t.length > 48 ? `${t.slice(0, 47)}…` : t;
    }
  }
  return idSuffix ? `New conversation · ${idSuffix}` : "New conversation";
}

/** Persist every conversation and the active id across page reloads. */
function saveConversations(convs: Conversation[], activeId: string): void {
  try {
    localStorage.setItem(
      STORAGE_CONVS,
      JSON.stringify(convs, (key, value) =>
        key === "images" ? undefined : value
      )
    );
    localStorage.setItem(STORAGE_ACTIVE, activeId);
  } catch {
    // Storage may be unavailable (private mode, quota); persistence is a
    // best-effort enhancement, so failures are ignored.
  }
}

/** Read the legacy single-conversation history, if any. */
function loadLegacyHistory(): ChatMessage[] {
  try {
    const raw = localStorage.getItem(LEGACY_HISTORY);
    if (!raw) return [];
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(isValidMessage);
  } catch {
    return [];
  }
}

function safeGetItem(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

function loadActiveId(): string | null {
  return safeGetItem(STORAGE_ACTIVE);
}

/**
 * Restore the persisted conversations. When none exist (first run) it
 * migrates the legacy single conversation into a one-item list, and returns
 * an empty list only when there is genuinely nothing to restore.
 */
function loadConversations(): Conversation[] {
  try {
    const raw = localStorage.getItem(STORAGE_CONVS);
    if (raw) {
      const parsed: unknown = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        const convs = parsed.filter(isValidConversation).map((c) => ({
          ...c,
          profileId: c.profileId ?? DEFAULT_PROFILE_ID,
        }));
        if (convs.length > 0) return convs;
      }
    }
    const legacy = loadLegacyHistory();
    if (legacy.length > 0) {
      return [
        {
          id: newId(),
          title: deriveTitle(legacy),
          model: safeGetItem(LEGACY_MODEL) ?? "",
          messages: legacy,
          profileId: DEFAULT_PROFILE_ID,
        },
      ];
    }
  } catch {
    return [];
  }
  return [];
}

/**
 * A stateful conversation store for the LLM panel. It owns the conversation
 * list, the active conversation, and per-conversation metrics (token usage and
 * context windows), and persists across page reloads. The panel (llm.ts) is a
 * thin DOM controller over this store: it renders `getConversations()` /
 * `getActive()` and forwards user actions to the mutators.
 */
export interface ConversationStore {
  /** The id of the active conversation. */
  activeId(): string;
  /** The active conversation. */
  getActive(): Conversation;
  /** All conversations, in display order. */
  getConversations(): Conversation[];
  /** Latest prompt-token count for a conversation, if any. */
  getPromptTokens(id: string): number | undefined;
  /** Record the latest prompt-token count for a conversation. */
  setPromptTokens(id: string, n: number): void;
  /** Context window (n_ctx) for a model id, if known. */
  getContextWindow(model: string): number | undefined;
  /** Record a model's context window (n_ctx). */
  setContextWindow(model: string, n: number): void;
  /** Start a new empty conversation (inheriting `model`) and activate it. */
  newConversation(model: string): void;
  /** Switch the active conversation to the one with this id. */
  switchTo(id: string): void;
  /**
   * Delete the conversation with this id (and its history). If it was active,
   * the first remaining conversation becomes active; if it was the only one, a
   * fresh empty conversation is seeded so the store keeps at least one.
   */
  deleteConversation(id: string): void;
  /** Set the active conversation's model choice. */
  setActiveModel(model: string): void;
  /**
   * Set the active conversation's profile, and clear its cached startup-hook
   * output (it belongs to the previous profile's command, not the new one's).
   */
  setActiveProfile(profileId: string): void;
  /**
   * Point every conversation on `fromId` at `toId` instead — used when a
   * profile is deleted, so its conversations fall back to another profile
   * (the default) rather than referencing a profile that no longer exists.
   */
  reassignProfile(fromId: string, toId: string): void;
  /**
   * Record the active conversation's startup-hook output after it has run,
   * so later turns reuse it instead of re-running the command.
   */
  setHookOutput(output: string): void;
  /** Retitle the active conversation from its first user message. */
  retitleActive(): void;
  /** Append a message to the active conversation (the single append point). */
  appendMessage(msg: ChatMessage): void;
  /** Truncate the active history back to `n` messages (failure rollback). */
  rollbackTo(n: number): void;
  /**
   * Atomically commit a completed chat turn: record the turn's prompt-token
   * count, retitle the conversation from its first user message, and persist.
   * The single gate the panel uses after a successful turn, so the store's
   * retitle/persist/token invariants can't be forgotten by a caller.
   */
  commitTurn(usage?: { promptTokens: number }): void;
  /** Persist the store. */
  persist(): void;
}

/** Build a conversation store from persisted state (with legacy migration). */
export function createConversationStore(): ConversationStore {
  let convs: Conversation[] = loadConversations();
  let activeId: string = loadActiveId() ?? "";

  // Always keep at least one conversation so getActive() is total: seed a
  // fresh empty one on first run.
  if (convs.length === 0) {
    const id = newId();
    convs = [
      {
        id,
        title: deriveTitle([], id.slice(0, 4)),
        model: "",
        messages: [],
        profileId: DEFAULT_PROFILE_ID,
      },
    ];
  }
  // Pick the active conversation: a stored id if it still exists, else the
  // first restored one.
  if (!convs.some((c) => c.id === activeId)) {
    activeId = convs[0].id;
  }

  /** Per-conversation token usage, so each resumed chat shows its own %. */
  const promptTokens = new Map<string, number>();
  /** Context window (n_ctx) for each model id, as reported by the proxy. */
  const contextWindow = new Map<string, number>();

  const getActive = (): Conversation =>
    convs.find((c) => c.id === activeId) ?? convs[0];

  return {
    activeId: () => activeId,
    getActive,
    getConversations: () => convs,
    getPromptTokens: (id) => promptTokens.get(id),
    setPromptTokens: (id, n) => {
      promptTokens.set(id, n);
    },
    getContextWindow: (model) => contextWindow.get(model),
    setContextWindow: (model, n) => {
      contextWindow.set(model, n);
    },
    newConversation(model) {
      const id = newId();
      convs = [
        {
          id,
          title: deriveTitle([], id.slice(0, 4)),
          model,
          messages: [],
          profileId: DEFAULT_PROFILE_ID,
        },
        ...convs,
      ];
      activeId = id;
      promptTokens.delete(id);
    },
    switchTo(id) {
      if (convs.some((c) => c.id === id)) activeId = id;
    },
    deleteConversation(id) {
      if (!convs.some((c) => c.id === id)) return;
      promptTokens.delete(id);
      convs = convs.filter((c) => c.id !== id);
      if (convs.length === 0) {
        const fresh = newId();
        convs = [
          {
            id: fresh,
            title: deriveTitle([], fresh.slice(0, 4)),
            model: "",
            messages: [],
            profileId: DEFAULT_PROFILE_ID,
          },
        ];
        activeId = fresh;
      } else if (activeId === id) {
        activeId = convs[0].id;
      }
    },
    setActiveModel(model) {
      getActive().model = model;
    },
    setActiveProfile(profileId) {
      const active = getActive();
      active.profileId = profileId;
      // A cached startup-hook output belongs to the profile that produced
      // it; keeping it around after switching profiles would inject a stale
      // command's output as if it were the new profile's.
      active.hookOutput = undefined;
    },
    reassignProfile(fromId, toId) {
      for (const c of convs) {
        if (c.profileId === fromId) c.profileId = toId;
      }
    },
    setHookOutput(output) {
      getActive().hookOutput = output;
    },
    retitleActive() {
      const active = getActive();
      active.title = deriveTitle(active.messages);
    },
    appendMessage(msg) {
      getActive().messages.push(msg);
    },
    rollbackTo(n) {
      getActive().messages.length = n;
    },
    commitTurn(usage) {
      if (usage) promptTokens.set(activeId, usage.promptTokens);
      const active = getActive();
      active.title = deriveTitle(active.messages);
      saveConversations(convs, activeId);
    },
    persist() {
      saveConversations(convs, activeId);
    },
  };
}
